import React, { useEffect, useState, useRef } from "react";



import { getStore, updStore, gen16CodeId,  ObjectKeys} from "../../../stores/Utils";

import { TabsHRM_Cmpt } from "../../../components";

import "./dashboard.css"
import { EmployeesDashboard_Cmpt, TimeCardDashboard_Cmpt } from "..";
import {  getall_employee, parseTimeClock, search_employee } from "../services/server_fetching";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";



const TimeCardDashboard = TimeCardDashboard_Cmpt();
const EmployeesDashboard = EmployeesDashboard_Cmpt();


const TabsHRM = TabsHRM_Cmpt();



const EmployeeDashboard  = ({ data, elmId, updObs }) => {
	const [initialize, setInitialize] = useState(false);
	const [, set_obs] = useState(0);
	const [view, set_view] = useState(1);


	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
			get_balances_by_type("global_accounts","global_account_params",handle_getall_employee);
			updStore("cmpByPayStubMayor",{})
			
		}
	});





	const handle_getall_employee =  (v) => {
		getall_employee(cb_result)
	}

	const cb_result = async (f, v) => {
		set_obs(gen16CodeId())
	};


	

	

	return (

	<div className="">
			<div style={{marginTop: 45}}/>
			<TabsHRM  
				indexTab={view} 
				data={[
					{key:1,label:"Empleados"}, 
					{key:2,label:"TimeCard"}
				]} 
				updateIndex={set_view}  
			/>
				


				<OpacityView viewId={1} activeView={view}>
					<EmployeesDashboard />
				</OpacityView>


				<OpacityView viewId={2} activeView={view}>
					<TimeCardDashboard />
				</OpacityView>
			
		</div>
	);
};

export default EmployeeDashboard;


const OpacityView  = ({ viewId, activeView, children }) => {
	return(
		<div className={"opacityView"} style={{opacity : viewId=== activeView?1:0 }}>
			{viewId=== activeView?children:null}
		</div>
	)
}