const middleWeek = (date) => {
    let dytt = (new Date(date));
    let dOW = dytt.getDay();
    let ddiff = 0;
    if(dOW>3){
        ddiff = dOW-3
    }
    else if(dOW<3){
        ddiff = dOW-3
    }
    let DD = dytt.getDate() - ddiff;
    let wkDay = new Date(dytt.setDate(DD));
    let week = getWeek(wkDay);
    return week
}


export const parseTimeClock = (jj) => {
    let ded = {}
    let regexSpace = /\t/g;
    jj && jj.split("\n").map((ff,ind)=>{
        ff = ff.split("\r").join("")
        if(ff.indexOf("No")<0){
            let arrS = ff.split(regexSpace);
            if(arrS.length===7){
                let EnNo = arrS[2].trim();
                let dateArr = arrS[6].split("  ");
                let date =  dateArr[0];
              


                let week = middleWeek(date)


            
                let ta = dateArr[1].split(":");
                let time = ta[0]*60 + ta[1]*1;

                let mode = arrS[4].trim();
              
                if(!ded[EnNo]){
                    ded[EnNo] = {}
                }
                if(!ded[EnNo][week]){
                    ded[EnNo][week] = {}
                }
                if(!ded[EnNo][week][date]){
                    ded[EnNo][week][date] = {}
                }
                
                if(!ded[EnNo][week][date][time]){
                    ded[EnNo][week][date][time] = {}
                }
                if(!ded[EnNo][week][date][time][mode]){
                    ded[EnNo][week][date][time][mode] = 1
                }
            }
        }
    })
   
    let dayOfW = Array.from(Array(7).keys())
    let list = []
   
    ObjectKeys(ded).map(uss=>{
        ObjectKeys(ded[uss]).map(week=>{
            let weekHourly = {}
            let period = null;


            dayOfW.map(ky=>{
                weekHourly[ky] = {active: false};
            });


            ObjectKeys(ded[uss][week]).map(date=>{

              
                let mmO = minMaxObjK(ded[uss][week][date])

                let startMode = ObjectKeys(ded[uss][week][date][mmO[0]]);

                let endMode = ObjectKeys(ded[uss][week][date][mmO[1]]);
                period = getWeekDetailsByDay(new Date(date));
                   
                let itm = {
                    start: mmO[0]*1,
                    startMode,
                    end: mmO[1]*1,
                    endMode,
                    active:true,
                }

                let dayWeek = new Date(date).getDay();
                
                weekHourly[dayWeek] = itm;
            })


            let itmU = {
                userTC: uss,
                week,
                hourly: weekHourly,
                period
            }

            list.push(itmU)
        })
    })
    //console.log(list)
    updStore("timeCard",list)
    return list;
}




const minMaxObjK =  (obj) => {
    let max = 0;
    let min = 10000000000;
    ObjectKeys(obj).map(mntI=>{
        let mnt = mntI*1;
        if(max<mnt){
            max=mnt;
        }
        if(mnt<min){
            min=mnt;
        }
    })
    return [min,max]
}




